  "Amatörde adın duyuldu. İki bölgesel organizasyon seni profesyonel kadrosuna istiyor!": "Twoje nazwisko krąży po scenie amatorskiej. Dwie regionalne organizacje chcą cię w składzie zawodowym!",
  "🎟️ Dean Wyatt ayağa kalktı: \"{0}, UCC’ye hoş geldin!\"": "🎟️ Dean Wyatt wstał: „{0}, witaj w UCC!”",
  "Kazandın ama Dean etkilenmedi: \"Biraz daha gelişsin.\" Diğer kapılar açık.": "Wygrałeś, ale Dean nie był pod wrażeniem: „Niech się jeszcze rozwinie”. Inne drzwi są otwarte.",
  "DWCS kötü geçti. UCC kapısı şimdilik kapandı.": "DWCS poszło źle. Drzwi do UCC są na razie zamknięte.",
