  "📉 {0} seni kadrodan çıkardı. Kariyer bitmedi, ama yeniden inşa etmen lazım.": "📉 {0} wyrzuciło cię ze składu. Kariera się nie skończyła, ale musisz się odbudować.",
  "📈 Artık bir “{0}” dövüşçüsüsün. UCC maaşını yeniden düzenlemek istiyor.": "📈 Jesteś teraz zawodnikiem z grupy „{0}”. UCC chce zmienić twoje wynagrodzenie.",
  "📜 {0} kontratın bitti. Menajerinin telefonu susmuyor.": "📜 Twój kontrakt z {0} wygasł. Telefon twojego menedżera się urywa.",
  "📞 Telefon çaldı. Arayan: Dean Wyatt. “Seni izliyorum evlat. Challenger Series’e gel, kendini göster.”": "📞 Zadzwonił telefon. To Dean Wyatt. „Obserwuję cię, młody. Przyjdź do Challenger Series i pokaż, co potrafisz”.",
