  "💞 {0} artık sevgilin! Kamp motivasyonu +1. (Popülerlik +{1})": "💞 {0} jest teraz twoją partnerką! Motywacja na obozie +1. (Popularność +{1})",
  "{0} ile yollarınızı ayırdınız. Zor bir veda. (Motivasyon -1)": "Ty i {0} poszliście w swoje strony. Trudne pożegnanie. (Motywacja -1)",
