  "ZEN Championship başkanı": "Przewodniczący ZEN Championship",
  "Saygı ve disiplin ister. Trash talk’tan hoşlanmaz.": "Wymaga szacunku i dyscypliny. Nie lubi trash talku.",
  "VIP MMA kurucusu": "Założyciel VIP MMA",
  "Show her şeydir. Para konuşur.": "Show jest wszystkim. Pieniądze rozmawiają.",
