  "Taraftar": "Fani",
  "Motivasyon": "Motywacja",
  "Yaşam": "Życie",
  "Soru": "Pytanie",
  "Kampın {n}. haftası. Ciğerler yanıyor ama zihin berrak. 🥊": "Tydzień {n} obozu. Płuca płoną, ale głowa czysta. 🥊",
  "Sabah 5’te koşu, öğlen spar, akşam grappling. {rakip}, ben hazırım. #Kamp": "Bieg o 5 rano, sparing w południe, grappling wieczorem. {rakip}, jestem gotowy. #Obóz",
  "{hoca} bugün beni yere serdi. Kafeste kimse bunu yapamayacak. 😤": "{hoca} dziś mnie położył. Nikt w klatce tego nie zrobi. 😤",
  "Yeni bir silah geliştiriyoruz. Maç gecesi göreceksiniz… 🤫": "Budujemy nową broń. Zobaczycie ją w noc walki… 🤫",
  "Kilo kontrolde, zihin net. {rakip} gelsin.": "Waga pod kontrolą, głowa czysta. Dawać {rakip}.",
  "{salon}’da bir gece daha. Işıklar sönene kadar buradayım. 💡": "Kolejna noc w {salon}. Jestem tu, dopóki nie zgaśnie światło. 💡",
  "Bugün 10 raunt spar. Yoruldum ama durmadım.": "Dziś 10 rund sparingu. Zmęczony, ale się nie zatrzymałem.",
  "Video analiz günü: {rakip}’in her hareketini ezberliyorum. 🎬": "Dzień analizy: uczę się na pamięć każdego ruchu {rakip}. 🎬",
  "Buz banyosu, masaj, uyku. Savaşçı dinlenmeyi de bilir. 🧊": "Lodowa kąpiel, masaż, sen. Wojownik umie też odpoczywać. 🧊",
  "Kamp güncellemesi: sağlıklı, aç ve tehlikeli. 🐺": "Aktualizacja z obozu: zdrowy, głodny i niebezpieczny. 🐺",
  "{rakip} kafeste beni görünce kaçacak yer arayacak. 😂": "{rakip} będzie szukał, gdzie uciec, gdy zobaczy mnie w klatce. 😂",
  "{rakip}, sosyal medyada çok cesursun. Kafeste görüşürüz.": "{rakip}, w mediach społecznościowych jesteś bardzo odważny. Do zobaczenia w klatce.",
  "Bu gece {rakip} uyumayacak. Çünkü maç gecesi uyutacağım. 💤": "{rakip} nie zaśnie dziś w nocy. Bo ja go uśpię w noc walki. 💤",
  "{rakip} diye bir dövüşçü yok, sadece bir sonraki kurbanım var.": "Nie ma zawodnika o nazwisku {rakip}, jest tylko moja kolejna ofiara.",
  "{rakip} hayranları, şimdiden mendilleri hazırlayın. 🤧": "Fani {rakip}, szykujcie chusteczki. 🤧",
  "{rakip}’in çenesi o kadar dayanıklı değil, herkes biliyor.": "Szczęka {rakip} nie jest taka twarda, wszyscy to wiedzą.",
  "Kamera önünde herkes aslan. Kafes kapısı kapanınca görürüz {rakip}.": "Przed kamerą każdy jest lwem. Zobaczymy, gdy zamkną się drzwi klatki, {rakip}.",
  "{rakip}, hazır ol. Kariyerinin en kötü gecesi yaklaşıyor.": "{rakip}, szykuj się. Nadchodzi najgorsza noc twojej kariery.",
  "Söylediklerimin arkasındayım: {rakip} bu maçı bitiremeyecek.": "Podtrzymuję: {rakip} nie dokończy tej walki.",
  "{sampiyon}, kemerini hazırla. Geliyorum. 🏆": "{sampiyon}, szykuj pas. Idę. 🏆",
  "{sampiyon} benden kaçıyor. {org}, bu maçı yapın!": "{sampiyon} przede mną ucieka. {org}, zestawcie tę walkę!",
  "Sıklette kimse benimle dövüşmek istemiyor. Sıradaki kim? 👀": "Nikt w dywizji nie chce ze mną walczyć. Kto następny? 👀",
  "{sampiyon}, tahtında rahat oturma. Sıra bende.": "{sampiyon}, nie rozsiadaj się wygodnie na tym tronie. Jestem następny.",
  "İlk 5’e giren herkese açık davet: kafeste görüşelim.": "Otwarte zaproszenie dla każdego z top 5: do zobaczenia w klatce.",
  "{org}, bana bir şampiyonluk maçı borçlusunuz. Hak ettim.": "{org}, jesteście mi winni walkę o tytuł. Zasłużyłem.",
  "Adımı unutmayın. Yakında o kemer bende olacak.": "Zapamiętajcie moje nazwisko. Wkrótce ten pas będzie mój.",
  "{rakip} gerçek bir savaşçı. Maç gecesi en iyi hâlimizle karşılaşacağız. 🤝": "{rakip} to prawdziwy wojownik. Spotkamy się w najlepszej formie w noc walki. 🤝",
  "Rakibime saygım sonsuz. Ama kazanan ben olacağım.": "Ogromny szacunek dla rywala. Ale to ja wygram.",
  "{hoca} ve tüm takımıma teşekkürler. Bu yol tek başına yürünmez.": "Dzięki dla {hoca} i całej drużyny. Nikt nie idzie tą drogą sam.",
  "Sıklette herkes çok çalışıyor. Bu yüzden bu spor güzel.": "Wszyscy w dywizji ciężko pracują. To czyni ten sport pięknym.",
  "Yenildiğim her maç bana bir şey öğretti. Hepsine minnettarım.": "Każda porażka czegoś mnie nauczyła. Jestem za wszystkie wdzięczny.",
  "Rakiplerime saygı, taraftarlara sevgi. Gerisi kafeste. 🙏": "Szacunek dla rywali, miłość dla fanów. Reszta dzieje się w klatce. 🙏",
  "{takipci} kişi! İnanılmaz. Her birinize teşekkür ederim. ❤️": "{takipci} ludzi! Niesamowite. Dziękuję każdemu z was. ❤️",
  "Maç gecesi tribünler yine bizim olsun! Kim geliyor? 🙌": "Zawładnijmy znowu trybunami w noc walki! Kto idzie? 🙌",
  "Bir taraftarım bugün bana el yazısı mektup verdi. Ağladım. 🥹": "Fan wręczył mi dziś odręcznie napisany list. Popłakałem się. 🥹",
  "{memleket}, bu zafer senin için!": "{memleket}, to zwycięstwo jest dla ciebie!",
