  "🔥 İNTİKAM GECESİ: {0}, kendisini yenen {1} karşısında. İlk maç {2} lehine bitmişti. Bu sefer?": "🔥 NOC ZEMSTY: {0} staje przed {1}, który go pokonał. Pierwszą walkę wygrał {2}. A teraz?",
  "🔁 RÖVANŞ: {0} ve {1} yeniden karşı karşıya. İlk maçın galibi {2}. Tarih tekerrür eder mi?": "🔁 REWANŻ: {0} i {1} znów się spotykają. Pierwszą walkę wygrał {2}. Czy historia się powtórzy?",
  "🏆 KEMER SAVAŞI: {0} şampiyonu {1}, tahtını yükselen isim {2}’ye karşı koruyor. 5 raunt, tek kemer.": "🏆 WOJNA O PAS: mistrz {0} {1} broni tronu przed wschodzącym {2}. 5 rund, jeden pas.",
  "🏆 UNVAN SAVUNMASI: Şampiyon {0}, aç kurt {1} karşısında. Kemer el değiştirir mi?": "🏆 OBRONA TYTUŁU: mistrz {0} kontra głodny wilk {1}. Czy pas zmieni właściciela?",
  "📈 YENİLMEZLİK SERİSİ: {0} {1} maçtır kaybetmiyor. {2} bu seriyi bitirecek kişi olabilir mi?": "📈 SERIA BEZ PORAŻKI: {0} nie przegrał od {1} walk. Czy to {2} ją przerwie?",
  "⚔️ STİL SAVAŞI: {0} ustası {1} vs {2} uzmanı {3}. Vuruşçu mu kazanır, güreşçi mi?": "⚔️ STARCIE STYLÓW: mistrz {0} {1} kontra specjalista {2} {3}. Stójkowicz czy parterowiec?",
  "🎤 SÖZ SAVAŞI: {0} haftalardır {1} hakkında konuşuyor. Kafeste sözlerin bedeli ödenecek.": "🎤 WOJNA NA SŁOWA: {0} od tygodni mówi o {1}. W klatce słowa mają swoją cenę.",
  "📰 {0} bu hafta: {1} vs {2}. Bahisçiler {3} tarafını favori görüyor.": "📰 W tym tygodniu w {0}: {1} vs {2}. Bukmacherzy stawiają na {3}.",
  "{0} ile kazandı": "wygrał przez {0}",
  "{0} ile kaybetti": "przegrał przez {0}",
  "MMA Türkiye": "Świat MMA",
  "SON DAKİKA: {0}, {1} {2} karşısında {3}.": "PILNE: {0}, {3} przeciw {1} {2}.",
