  "Maç gecesi tahmini yapan her uzman: 🧙‍♂️ Maç sonucu: 🤡": "Każdy ekspert typujący w noc walki: 🧙‍♂️ Wynik: 🤡",
  "🎥 GÜNÜN KLİBİ: {p}’ın son maçındaki o an. 1 milyon izlenmeye koşuyor.": "🎥 KLIP DNIA: ten moment z ostatniej walki {p}. Pędzi w stronę miliona wyświetleń.",
