  "Bir maçı hangi hareketle bitirirsen o hareket ustalık kazanır. Teknik çalışması ve spar da ustalık verir. Özel hareketler dövüş sırasında riskli ama görkemli fırsatlar açar. Gelişim puanın:": "Każdy ruch, którym skończysz walkę, zyskuje mistrzostwo. Trening techniki i sparingi też dają mistrzostwo. Specjalne ruchy otwierają w walkach ryzykowne, ale chwalebne szanse. Twoje punkty rozwoju:",
