  "Kalan adımları biz seçelim: branş, sıklet, görünüm ve hikâye. Hemen salona gir, her şeyi sonradan oynarken öğrenirsin.": "Resztę wybierzemy za ciebie: styl, kategorię wagową, wygląd i historię. Od razu na salę, a wszystkiego nauczysz się w trakcie gry.",
  "Hemen başla": "Zacznij teraz",
  "ya da DEVAM ile karakterini adım adım kendin kur": "albo stuknij DALEJ i zbuduj zawodnika krok po kroku",
  "🏁 Rekabet bitti! {0} sonunda kabul etti: \"Sen daha iyiydin, {1}.\" Aranızdaki seri: {2}. Popülerlik +5.": "🏁 Rywalizacja skończona! {0} w końcu przyznał: „Byłeś lepszy, {1}”. Seria: {2}. Popularność +5.",
  "Bugün kafeste daha iyi olan kazandı. Saygılar {0}. Bu rekabet beni daha iyi bir dövüşçü yaptı.": "Dziś wygrał lepszy. Szacunek, {0}. Ta rywalizacja zrobiła ze mnie lepszego zawodnika.",
  "🏁 {0} emekliliğini açıkladı: \"Kariyerimdeki en zor rakip sendin, {1}.\" Seriyi sen kazandın: {2}.": "🏁 {0} ogłosił koniec kariery: „Byłeś najtrudniejszym rywalem mojej kariery, {1}”. Serię wygrałeś ty: {2}.",
  "🏁 {0} emekliliğini açıkladı. Aranızdaki seri: {1}. Onu hiç tam geçemedin; bu hikâye böyle bitti.": "🏁 {0} ogłosił koniec kariery. Seria: {1}. Nigdy do końca go nie przeskoczyłeś; tak kończy się ta historia.",
  "⚔️ Ezeli rakibin {0} karşısında kazandın! Aranızdaki seri: {1}.": "⚔️ Pokonałeś arcyrywala {0}! Seria: {1}.",
  "Bu gece senin gecendi. Ama bu iş bitmedi, {0}.": "Dziś była twoja noc. Ale to się nie skończyło, {0}.",
  "Rövanş istiyorum. Organizasyon duysun!": "Chcę rewanżu. Organizacja, słyszycie?",
  "Şans bir kez güler. Üçüncü maçta görüşürüz.": "Szczęście uśmiecha się tylko raz. Do zobaczenia w następnej.",
  "⚔️ Ezeli rakibinle berabere. Aranızdaki seri: {0}. Kimse tatmin olmadı.": "⚔️ Remis z arcyrywalem. Seria: {0}. Nikt nie jest zadowolony.",
  "⚔️ {0} yine kazandı. Aranızdaki seri: {1}. Bu iş bitmedi.": "⚔️ {0} znów wygrał. Seria: {1}. To się nie skończyło.",
  "Söylemiştim. Kafeste ne zaman karşılaşsak aynı son. 😏": "Mówiłem. Za każdym razem w klatce ten sam koniec. 😏",
  "{0}, bir daha karşıma çıkmadan önce iki kere düşün.": "{0}, pomyśl dwa razy, zanim znowu staniesz naprzeciw mnie.",
  "Kral benim. Anlaşıldı mı?": "Król jestem ja. Jasne?",
  "🗡️ {0} maçtan sonra mikrofonu aldı: \"Bu daha başlangıç. Kafeste her karşılaştığımızda aynı sonuç olacak.\" Bu isim peşini kolay bırakmayacak: artık bir ezeli rakibin var.": "🗡️ {0} po walce wziął mikrofon: „To dopiero początek. Za każdym razem w klatce skończy się tak samo”. Ten zawodnik łatwo nie odpuści: masz arcyrywala.",
  "{0} iyi dövüşçü ama bana göre değil. Ne zaman isterse tekrar.": "{0} to dobry zawodnik, ale nie mój poziom. Rewanż, kiedy tylko zechce.",
  "🗡️ {0} kameralara konuştu: \"{1} yenilmez sanılıyor. O balonu ben patlatacağım.\" Yeni bir ezeli rakibin var.": "🗡️ {0} powiedział do kamer: „Wszyscy myślą, że {1} jest nie do pokonania. Przebiję ten balon”. Masz nowego arcyrywala.",
  "{0}, kaçamazsın. Sıra bende.": "{0}, nie uciekniesz. Teraz ja.",
  "{1} karşısında kazanmak mı? Onu ben de yenerdim. Asıl sınav benim, {0}.": "Wygrać z {1}? Ja też bym go pokonał. Prawdziwy sprawdzian to ja, {0}.",
  "Herkes seni konuşuyor {0}. Ben hâlâ o geceyi hatırlıyorum. 😏": "Wszyscy o tobie mówią, {0}. A ja wciąż pamiętam tamtą noc. 😏",
  "Güzel galibiyet {0}. Ama bir gün yine karşılaşacağız.": "Ładne zwycięstwo, {0}. Ale kiedyś znowu się spotkamy.",
  "{0} formda görünüyor. Ben de. Tarih verin.": "{0} jest w formie. Ja też. Podajcie datę.",
  "{1} bile seni yendi. Ben sana söylemiştim, {0}.": "Nawet {1} cię pokonał. Mówiłem ci, {0}.",
  "Kafeste yerin yok, {0}. Bunu en iyi ben biliyorum.": "Nie pasujesz do klatki, {0}. Nikt nie wie tego lepiej ode mnie.",
