  "İyi oynarsan kamp daha verimli geçer ve sakatlık riski azalır. Oynamazsan kamp normal sonucunu verir.": "Zagraj dobrze, a obóz da więcej i ryzyko kontuzji spadnie. Pomiń, a obóz da zwykły wynik.",
