  "1. raunt: plan işliyor. {0} rakibinin zaafına yükleniyor, raundu açık ara aldı.": "Runda 1: plan działa. {0} atakuje słaby punkt i wyraźnie wygrał rundę.",
  "1. raunt: {0} raundu önde kapattı ama {1} hâlâ tehlikeli.": "Runda 1: {0} minimalnie wygrał rundę, ale {1} wciąż jest groźny.",
