  "İpucu: Hakarete espriyle, övünmeye sert, alaya soğukkanlı cevap ver.": "Wskazówka: na obelgę odpowiadaj żartem, na przechwałki ostro, na kpiny chłodno.",
  "{0} mi? Bu kafese değil, kreşe gitmeli.": "{0}? Ty powinieneś iść do przedszkola, nie do klatki.",
  "Şu surata bakın: daha önce çok dayak yediği belli.": "Spójrzcie na tę twarz: widać, że już nieźle oberwała.",
  "Onun antrenmanlarını izledim. Annem daha sert vuruyor.": "Widziałem twoje treningi. Moja mama bije mocniej.",
  "Tek yeteneği basın toplantısında uyumamak.": "Twój jedyny talent to nie zasnąć na konferencji.",
  "Ben bu sıkletin kralıyım. Onu ilk rauntta uyutacağım, yazın bir kenara.": "Jestem królem tej kategorii. Uśpię cię w pierwszej rundzie, zapisz to.",
  "Bana rakip bulamıyorlar, o yüzden bunu getirdiler.": "Nie mogą mi znaleźć rywala, więc przywieźli to.",
  "Kemeri şimdiden evime astım. Bu maç sadece formalite.": "Pas już wisi u mnie w domu. Ta walka to formalność.",
  "Benim ısınmam onun bütün kariyeri kadar sürüyor.": "Moja rozgrzewka trwa dłużej niż cała twoja kariera.",
  "Hahaha! {0} titriyor bakın, ellerine bakın!": "Hahaha! {0}, ręce ci się trzęsą, patrzcie!",
  "Kilo verirken ağladığını duydum. Çok tatlı.": "Podobno płaczesz przy zbijaniu wagi. Jakie to słodkie.",
  "Gözlerime bakamıyor bile. Daha şimdiden kaybetti.": "Nawet nie możesz spojrzeć mi w oczy. Już przegrana sprawa.",
  "Hocası bile onun yerine utanıyor, şu hâline bakın.": "Nawet twój trener się za ciebie wstydzi, popatrzcie.",
  "Kreş mi? Doğru, cumartesi seni orada bebek gibi uyutacağım.": "Przedszkole? Jasne, w sobotę uśpię cię jak dziecko.",
  "Annenle antrenman yapıyorsan bana da numarasını ver, belki bir şey öğrenirim.": "Jeśli trenujesz z mamą, daj mi jej numer, może się czegoś nauczę.",
  "Konuş, konuş. Cumartesi gecesi konuşamayacaksın.": "Gadaj, gadaj. W sobotę wieczorem nie będziesz w stanie.",
  "Laflar ucuz. Kafeste görüşürüz.": "Gadanie nic nie kosztuje. Do zobaczenia w klatce.",
  "Bir daha ağzını açarsan burada dağıtırım seni!": "Otwórz jeszcze raz usta, a rozwalę cię tutaj!",
  "Kapa çeneni yoksa ben kapatırım!": "Zamknij się albo ja cię zamknę!",
  "Kral mı? Son üç maçında yere kaç kez düştüğünü sayalım mı?": "Król? Policzymy, ile razy leżałeś w ostatnich trzech walkach?",
  "Kemeri evine asmışsın, güzel. Ben gelip alacağım.": "Pas wisi u ciebie w domu? Świetnie. Przyjdę i go zabiorę.",
  "İlk rauntta uyutacakmış… herhalde bu konuşmasıyla.": "Uśpi mnie w pierwszej rundzie… chyba tym przemówieniem.",
  "Tamam. Görürüz.": "Dobra. Zobaczymy.",
  "Saygı duyuyorum, iyi şanslar.": "Szanuję. Powodzenia.",
  "Gülmeye devam et. Son gülen iyi güler.": "Śmiej się dalej. Ten się śmieje, kto się śmieje ostatni.",
  "Ellerim titremiyor, sadece seni beklemekten sıkıldılar.": "Ręce mi się nie trzęsą, po prostu nudzi im się czekanie na ciebie.",
  "Gülüyor musun? Cumartesi gülemeyeceksin!": "Śmiejesz się? W sobotę nie będzie ci do śmiechu!",
  "Bir daha bana gülersen sahnede kavga çıkar!": "Zaśmiej się jeszcze raz, a będzie bójka na scenie!",
  "Hahaha, evet çok komiksin… dur, bunu anneme de anlatayım.": "Hahaha, tak, bardzo śmieszne… czekaj, opowiem mamie.",
  "Titriyorum çünkü burası çok soğuk, senin kariyerin gibi.": "Trzęsę się, bo tu zimno, jak w twojej karierze.",
