  "Ayrıntılı tarama ve tedavi. Hasar -4.": "Dokładne badania i leczenie. Uszkodzenia -4.",
  "Boş ver, devam": "Olej to, walcz dalej",
  "Raporu çekmeceye kaldır. Hiçbir şey değişmez.": "Schowaj raport do szuflady. Nic się nie zmienia.",
  "Doktor uyarısı": "Ostrzeżenie lekarza",
  "Rutin taramada küçük izler görüldü. \"Henüz endişelenecek bir şey yok, ama sparringde kafaya aldığın darbeleri azaltmalısın.\"": "Rutynowe badanie wykazało drobne ślady. \"Na razie nie ma powodu do obaw, ale ogranicz ciosy w głowę na sparingach.\"",
  "Kafa sparringini bırak": "Rzuć sparingi na głowę",
  "Bundan sonra hasar %25 daha az birikir. Canlı sparring keskinliği gider: Hız kalıcı -1.": "Od teraz uszkodzenia narastają o 25% wolniej. Tracisz ostrość z prawdziwych sparingów: Szybkość na stałe -1.",
  "Nörolog raporu": "Raport neurologa",
  "Tepki sürelerin yavaşlamış, baş ağrıların sık. Doktor ciddi: \"Çenen eskisi gibi değil. Kafeste daha çabuk sarsılacaksın.\"": "Twój refleks spowolnił, bóle głowy są częste. Lekarz jest poważny: \"Twoja szczęka nie jest już taka jak kiedyś. W klatce łatwiej cię zachwieją.\"",
  "8 hafta tam dinlenme": "8 tygodni pełnego odpoczynku",
  "Hasar -5, sağlık tamamen dolar.": "Uszkodzenia -5, zdrowie w pełni odnowione.",
  "Son uyarı": "Ostatnie ostrzeżenie",
  "Doktor gözlerinin içine bakıyor: \"Bir ağır nakavt daha hayatını değiştirebilir. Ailen için düşün.\"": "Lekarz patrzy ci w oczy: \"Jeszcze jeden ciężki nokaut może zmienić twoje życie. Pomyśl o rodzinie.\"",
  "Eldivenleri as": "Odwieś rękawice",
  "Sağlığın her şeyden önemli. Kariyer burada biter.": "Zdrowie jest najważniejsze. Kariera kończy się tutaj.",
