  "Riski bilerek devam et.": "Walcz dalej, znając ryzyko.",
  "Lisans askıya alındı": "Licencja zawieszona",
  "Atletik komisyon tarama sonuçlarını gördü ve dövüş lisansını askıya aldı. Ya emekli olacaksın ya da lisansı başka bir yerden alacaksın.": "Komisja sportowa zobaczyła wyniki i zawiesiła licencję. Albo przejdziesz na emeryturę, albo zdobędziesz licencję gdzie indziej.",
  "Onurlu bir veda.": "Honorowe pożegnanie.",
  "Başka bir eyaletten lisans al": "Zdobądź licencję w innym stanie",
  "Para ve itibar kaybı. Basın seni eleştirecek: popülerlik -8.": "Kosztuje pieniądze i reputację. Prasa cię skrytykuje: popularność -8.",
  "🧠 Kafa sparringini bıraktın. Daha az hasar alacaksın ama keskinliğin biraz azaldı.": "🧠 Rzuciłeś sparingi na głowę. Przyjmiesz mniej obrażeń, ale straciłeś trochę ostrości.",
  "🧠 Nörolog tedavisi iyi geldi. Beyin hasarı {0}/100.": "🧠 Leczenie u neurologa pomogło. Uszkodzenie mózgu {0}/100.",
  "🛌 8 hafta tam dinlendin. Baş ağrıların azaldı. Beyin hasarı {0}/100.": "🛌 Odpoczywałeś 8 tygodni. Bóle głowy zelżały. Uszkodzenie mózgu {0}/100.",
  "🧤 Doktorunu dinledin ve eldivenleri astın. Sağlığın için verilmiş en zor karar.": "🧤 Posłuchałeś lekarza i odwiesiłeś rękawice. Najtrudniejsza decyzja, podjęta dla zdrowia.",
  "📄 Başka bir eyaletten lisans aldın (${0}). Basın sert: \"Kim durduracak onu?\"": "📄 Zdobyłeś licencję w innym stanie (${0}). Prasa jest ostra: \"Kto go powstrzyma?\"",
  "🩺 Raporu çekmeceye kaldırdın.": "🩺 Schowałeś raport do szuflady.",
  "Doktorunu dinleyip zamanında bıraktı. Yıllar sonra bile hafızası yerinde, çocuklarına bütün maçlarını tek tek anlatıyor.": "Posłuchał lekarza i odszedł w porę. Po latach pamięć wciąż dopisuje, opowiada dzieciom każdą walkę.",
  "Kafeste aldığı darbelerin bedelini emeklilikte ödüyor: konuşması yavaşladı, isimleri unutuyor. Eski rakipleri onu ziyarete geliyor.": "Na emeryturze płaci cenę za klatkę: mowa zwolniła, zapomina imion. Dawni rywale przychodzą w odwiedziny.",
  "Sık sık baş ağrısı çekiyor ve bazı günler kelimeleri bulmakta zorlanıyor. Yine de salona gelip gençlere ders veriyor.": "Częste bóle głowy, czasem brakuje słów. Mimo to przychodzi na salę uczyć młodych.",
  "Kariyerin izleri hafif: arada bir baş ağrısı, soğuk havalarda eski nakavtları hatırlatan bir sızı.": "Kariera zostawiła lekkie ślady: czasem ból głowy, łupanie w zimne dni przypominające dawne nokauty.",
  "Kafesten sağlıklı çıktı. Zihni berrak, enerjisi yerinde; ikinci bir hayata hazır.": "Wyszedł z klatki zdrowy. Jasny umysł, pełen energii, gotowy na drugie życie.",
  "Dean Wyatt bizzat aradı: \"Hayranlar seni özledi. Bir ana maç, büyük bir çek. Ne dersin?\"": "Dean Wyatt zadzwonił osobiście: \"Fani tęsknią. Walka wieczoru, duży czek. Co ty na to?\"",
  "VIP MMA servet teklif ediyor: \"Efsanenin dönüşü\" diye bir gece kurmak istiyorlar.": "VIP MMA oferuje fortunę: chcą zorganizować galę \"Powrót legendy\".",
  "{0} arıyor: \"Seyircimiz seni bir kez daha görmek istiyor.\"": "Dzwoni {0}: \"Nasza publiczność chce cię zobaczyć jeszcze raz.\"",
  "🔥 {0} yıl sonra {1} geri dönüyor! {2} ile 2 maçlık kontrat (${3}).": "🔥 Po {0} latach {1} wraca! Kontrakt na 2 walki z {2} (${3}).",
  "🔥 EFSANE GERİ DÖNDÜ! {0}, {1} yıllık aradan sonra kafese galibiyetle döndü.": "🔥 LEGENDA WRÓCIŁA! {0} wrócił do klatki ze zwycięstwem po {1} latach przerwy.",
  "🔥 DÖNÜŞ ZAFERİ! Yıllar sonra hâlâ buradasın. Popülerlik +10.": "🔥 ZWYCIĘSKI POWRÓT! Po latach wciąż to masz. Popularność +10.",
  "💔 {0} dönüş maçını kaybetti. Seyirci yine de ayakta alkışladı.": "💔 {0} przegrał walkę powrotną. Publiczność i tak nagrodziła go owacją na stojąco.",
  "💔 Dönüş planladığın gibi gitmedi. Ama seyirci seni ayakta alkışladı.": "💔 Powrót nie poszedł zgodnie z planem. Ale publiczność nagrodziła cię owacją na stojąco.",
