  "Halka altın olunca KAÇ (⬇️ takedown'a karşı da). DİREKT ve TEKME hazırlığı keser.": "Gdy pierścień zrobi się złoty, UNIK (także przy ⬇️ sprowadzeniu). PROSTY i KOPNIĘCIE przerywają zamach.",
