  "🏆 Yükseliş Grand Prix'i daveti geldi! 8 amatör, tek kupa: şampiyon ve finalist profesyonel kapıyı açar.": "🏆 Zaproszenie na Grand Prix Awansu! 8 amatorów, jedno trofeum: mistrz i finalista otwierają drzwi do zawodowstwa.",
  "🏆 Yükseliş Grand Prix'ine katıldın: 8 amatör, üç maç. Profesyonel organizasyonlar izliyor.": "🏆 Wszedłeś do Grand Prix Awansu: 8 amatorów, trzy walki. Zawodowe organizacje patrzą.",
