  "🥈 Finalde kaybettin ama herkes seni izledi. Profesyonel organizasyonlar seni kadrosunda istiyor!": "🥈 Przegrałeś finał, ale wszyscy cię widzieli. Zawodowe organizacje chcą cię w składzie!",
